import {contentPolicyCommandApplicable,onCharacterContentPolicyReady} from '../safety/character-content-policy-client.mjs';
import { patchHtml } from './dom-patch.mjs';
import { HYPNOSIS_SCOPES, HYPNOSIS_COMMANDS } from './hypnosis-catalog.mjs';
import { hypnosisCommands, hypnosisCost, hypnosisBodyParts, hypnosisOrganTargetEligible, normalizeHypnosisBatch } from './hypnosis-model.mjs';
import { phoneIcon } from './icons.mjs';
import {personnelPermissions} from '../object-manager/personnel-permissions.mjs';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safePhoto=value=>/^(?:https?:|blob:|\/|data:image\/(?:png|jpeg|webp|gif);)/.test(String(value??''))?esc(value):'';
const rank=command=>command.tier==='TRIAL'?0:Number(command.tier.replace('VIP',''));

// Each source command keeps its own targets, numeric fields, duration and note.
// Categories are views over those contracts, never new command semantics.
export function mountHypnosisApp(container,{getSnapshot,stageHypnosis,onHome,notify,initialScope='personal',draftCache=new Map()}) {
 const doc=container.ownerDocument,win=doc.defaultView;
 let snapshot={people:[],energy:0,vipRank:0},scope=initialScope==='group'?'location':initialScope,lifetime='temporary',records=false,search='',modal=null,busy=false,destroyed=false,epoch=0,soundwave=false;
 const drafts=new Map(),opened=new Set(['TRIAL']),sessionChat={id:null};
 function saveDraft(){if(sessionChat.id!==null)draftCache.set(sessionChat.id,{drafts:[...drafts].map(([key,value])=>[key,{...value,targetIds:[...value.targetIds],partIds:[...value.partIds]}]),soundwave,lifetime,scope});}
 const data=command=>{const key=scope+':'+command.id;if(!drafts.has(key))drafts.set(key,{enabled:false,targetIds:[],partIds:[],minutes:10,number:command.numeric?.fallback??1,note:'',locationId:''});return drafts.get(key);};
 const peopleFor=command=>(snapshot.people??[]).filter(x=>x.present&&personnelPermissions(x).hypnosis&&x.hypnosisEligible!==false&&contentPolicyCommandApplicable(x,command));
 const commands=()=>hypnosisCommands(scope,lifetime);
 const chosen=()=>commands().filter(x=>data(x).enabled);
 const cost=command=>{const d=data(command);try{return hypnosisCost(command,{minutes:Number(d.minutes),number:Number(d.number),targetCount:d.targetIds.length,partCount:d.partIds.length});}catch{return 0;}};
 const total=()=>chosen().reduce((sum,x)=>sum+cost(x),0)+(soundwave&&scope==='personal'&&chosen().length?100:0);
 const names=d=>(snapshot.people??[]).filter(x=>d.targetIds.includes(x.id));
 const portrait=person=>safePhoto(person.photo)?`<img src="${safePhoto(person.photo)}" alt="${esc(person.name)}">`:`<span>${esc(person.name.slice(-1))}</span>`;
 function card(command){const d=data(command),locked=rank(command)>Number(snapshot.vipRank),selected=names(d);return `<article class="ip-source-command ${d.enabled?'is-active':''} ${locked?'is-locked':''}" data-source-command="${command.id}"><label class="ip-source-toggle"><input type="checkbox" data-feature="${command.id}" ${d.enabled?'checked':''} ${locked?'disabled':''}><span><strong>${esc(command.title)}</strong><small>${command.parts?'按部位与数值':command.numeric?'按'+esc(command.numeric.label):command.timed?'按分钟':'单次计费'} · ${locked?'未解锁':command.lifetime==='permanent'?'永久':'临时'}</small></span><b data-command-cost="${command.id}">${d.enabled?cost(command):command.parts?2:command.costValue}<small> MC${!d.enabled&&command.timed?'/分':''}</small></b></label><p>${esc(command.description)}</p>${d.enabled?`<div class="ip-source-params">${command.scope==='people'?`<button class="ip-target-field" data-picker="people" data-command-id="${command.id}"><span class="ip-target-avatars">${selected.slice(0,2).map(portrait).join('')||phoneIcon('person')}</span><span><small>目标人物</small><strong>${esc(selected.map(x=>x.name).join('、')||'点击选择人物')}</strong></span>${phoneIcon('chevron')}</button>`:`<div class="ip-target-field">${phoneIcon('location')}<span><small>${command.scope==='group'?'封闭空间 · 不限人数':'当前地点'}</small>${command.id==='vip5_open_space_common_sense'?`<select data-field="locationId" data-command-id="${command.id}" aria-label="常识修改作用地点">${[snapshot.location,...(snapshot.locationAncestors??[])].filter(Boolean).map(x=>`<option value="${esc(x.id)}" ${x.id===(d.locationId||snapshot.location?.id)?'selected':''}>${esc(x.name)}</option>`).join('')}</select>`:`<strong>${esc(snapshot.location?.name??'地点未确定')}</strong>`}</span></div>`}${command.timed?`<label class="ip-parameter"><span>时间 <small>分钟</small></span><input data-field="minutes" data-command-id="${command.id}" type="number" aria-label="${esc(command.title)}时间" min="1" max="1440" value="${esc(d.minutes)}"></label>`:''}${command.parts?`<button class="ip-target-field" data-picker="parts" data-command-id="${command.id}">${phoneIcon('sparkle')}<span><small>部位 · 最多 5 处</small><strong>${esc(hypnosisBodyParts(selected).filter(x=>d.partIds.includes(x.id)).map(x=>x.label).join('、')||'点击选择部位')}</strong></span>${phoneIcon('chevron')}</button>`:''}${command.numeric?`<label class="ip-parameter"><span>${esc(command.numeric.label)} <small>${esc(command.numeric.unit)}</small></span><input data-field="number" data-command-id="${command.id}" type="number" aria-label="${esc(command.title+command.numeric.label)}" min="${command.numeric.min}" max="${command.numeric.max}" value="${esc(d.number)}"></label>`:''}<textarea data-field="note" data-command-id="${command.id}" aria-label="${esc(command.title)}备注" maxlength="1200" placeholder="${esc(command.placeholder||'补充目标、细节或限制…')}">${esc(d.note)}</textarea></div>`:''}</article>`;}
 function picker(){if(!modal)return '';const command=HYPNOSIS_COMMANDS.find(x=>x.id===modal.id),parts=modal.type==='parts',available=parts?hypnosisBodyParts(names(data(command))):peopleFor(command).filter(x=>!search||x.name.includes(search)),selected=new Set(modal.selected);return `<div class="ip-picker-backdrop" data-dismiss><section class="ip-picker-sheet" role="dialog" aria-modal="true" aria-labelledby="ip-picker-title"><i class="ip-sheet-handle"></i><header><button data-modal-cancel>取消</button><h2 id="ip-picker-title">${parts?'选择部位':'选择人物'}</h2><button data-modal-confirm>完成</button></header><p>${esc(command.title)} · ${parts?'最多 5 处':'可选择多个人 · 逐人结算'}</p>${!parts?`<label class="ip-search">${phoneIcon('search')}<input data-picker-search aria-label="搜索人物" placeholder="搜索姓名" value="${esc(search)}"></label><div class="ip-picker-context">${phoneIcon('location')}${esc(snapshot.location?.name??'当前地点')} · ${esc(snapshot.time)}</div>`:''}<div class="ip-picker-list ${parts?'is-parts':''}">${available.map(x=>`<button data-option="${esc(x.id)}" aria-label="选择${esc(x.name??x.label)}" aria-pressed="${selected.has(x.id)}">${!parts?`<span class="ip-picker-portrait">${portrait(x)}</span>`:''}<span><strong>${esc(x.name??x.label)}</strong>${!parts?`<small>${esc(x.activity||'此刻在这里')}</small>`:''}</span><i>${selected.has(x.id)?phoneIcon('check'):''}</i></button>`).join('')||'<div class="ip-empty">当前没有可选对象</div>'}</div><footer>已选 ${selected.size} ${parts?'处':'人'}<button class="ip-primary" data-modal-confirm>确认选择${phoneIcon('check')}</button></footer></section></div>`;}
 function render(){if(destroyed)return;saveDraft();const optionFocus=doc.activeElement?.dataset?.option,scroll=container.querySelector('.ip-scroll')?.scrollTop??0;let rows;
 if(records)rows=(snapshot.history??[]).map(x=>`<article class="ip-history-row"><strong>${esc(x.title||'催眠指令')}</strong><p>${esc(x.targetText||'')} · ${esc(x.status||'待安排')}</p><small>${esc(x.time||snapshot.time)} · ${Number(x.cost??0)} MC</small></article>`).join('')||'<div class="ip-empty">当前没有暂存的催眠操作</div>';
 else rows=['TRIAL','VIP1','VIP2','VIP3','VIP4','VIP5'].map(tier=>{const list=commands().filter(x=>x.tier===tier);return list.length?`<details class="ip-source-tier" data-tier="${tier}" ${opened.has(tier)?'open':''}><summary><strong>${tier==='TRIAL'?'试用区':tier}</strong><span>${list.filter(x=>data(x).enabled).length}/${list.length} 已选</span>${phoneIcon('chevron')}</summary>${list.map(card).join('')}</details>`:'';}).join('')||`<div class="ip-empty">原卡没有永久${scope==='group'?'集体':'地点'}催眠指令。</div>`;
 patchHtml(container,`<section class="ip-app-page ip-source-app"><div class="ip-source-heading"><div><p class="ip-kicker">HYPNOSIS APP</p><h1 class="ip-title">${records?'催眠记录':'催眠'}</h1></div><div class="ip-energy"><small>MC 能量</small><strong>${Number(snapshot.energy??0).toLocaleString()}</strong></div></div>${!records?`<nav class="ip-category-tabs" aria-label="催眠类别">${HYPNOSIS_SCOPES.filter(x=>x.id!=='group').map(x=>`<button data-app-scope="${x.id}" aria-pressed="${scope===x.id}">${phoneIcon(x.icon)}${x.name}</button>`).join('')}</nav><div class="ip-source-controls"><div class="ip-tabs" role="group" aria-label="催眠时效"><button data-app-lifetime="temporary" aria-pressed="${lifetime==='temporary'}">临时催眠</button><button ${scope==='personal'?'':'hidden'} data-app-lifetime="permanent" aria-pressed="${lifetime==='permanent'}">永久催眠</button></div>${scope==='personal'?`<button class="ip-soundwave" data-soundwave aria-pressed="${soundwave}" ${Number(snapshot.vipRank)<1?'disabled':''}>${phoneIcon('wave')}声波 <small>+100 MC</small></button>`:''}</div>`:''}<div class="ip-scroll ip-source-scroll">${!records?`<p class="ip-source-hint">${scope==='personal'?'指定人物，可复选多人；每位目标独立计费':scope==='group'?'原规则的封闭空间范围催眠，不限制人数':'覆盖所在地点的范围催眠 · 仅临时生效'}</p>`:''}${rows}</div>${!records?`<footer class="ip-source-submit"><div><small>已选 ${chosen().length} 条</small><strong data-batch-cost>${total()} <span>MC</span></strong></div><button class="ip-primary" data-stage ${!chosen().length||busy||snapshot.pendingStart?'disabled':''}>${busy?'正在暂存…':snapshot.pendingStart?'已暂存':snapshot.hypnosisActive?'追加催眠':'启动催眠'}${phoneIcon('hypnosis')}</button></footer>`:''}${picker()}</section>`);
 container.querySelector('.ip-scroll')?.scrollTo(0,scroll);
 container.querySelectorAll('.ip-source-app> :not(.ip-picker-backdrop)').forEach(x=>x.inert=Boolean(modal));
 if(modal&&!container.querySelector('.ip-picker-sheet')?.contains(doc.activeElement))(optionFocus?[...container.querySelectorAll('[data-option]')].find(x=>x.dataset.option===optionFocus):container.querySelector('[data-modal-cancel]'))?.focus({preventScroll:true});
 }
 function closePicker(){const previous=modal;modal=null;render();if(previous)[...container.querySelectorAll('[data-picker]')].find(x=>x.dataset.commandId===previous.id&&x.dataset.picker===previous.type)?.focus({preventScroll:true});}
 async function refresh(){const token=++epoch;try{const next=await getSnapshot();if(destroyed||token!==epoch)return;if(sessionChat.id!==next.chatId){drafts.clear();modal=null;soundwave=false;const saved=draftCache.get(next.chatId);if(saved){for(const [key,value]of saved.drafts)drafts.set(key,{...value,targetIds:[...value.targetIds],partIds:[...value.partIds]});soundwave=saved.soundwave;lifetime=saved.lifetime;scope=saved.scope==='group'?'location':saved.scope;if(scope==='location')lifetime='temporary';}}const unchanged=JSON.stringify(snapshot)===JSON.stringify(next)&&container.firstElementChild;sessionChat.id=next.chatId;snapshot=next;if(unchanged)return;for(const [key,d]of drafts){const command=HYPNOSIS_COMMANDS.find(x=>key.endsWith(':'+x.id));if(!command)continue;const eligible=new Set(peopleFor(command).map(x=>x.id));d.targetIds=d.targetIds.filter(id=>eligible.has(id));if(command.parts){const validParts=new Set(hypnosisBodyParts(names(d)).map(x=>x.id));d.partIds=d.partIds.filter(id=>validParts.has(id));}}if(modal){const command=HYPNOSIS_COMMANDS.find(x=>x.id===modal.id),eligible=new Set((modal.type==='parts'?hypnosisBodyParts(names(data(command))):peopleFor(command)).map(x=>x.id));modal.selected=modal.selected.filter(id=>eligible.has(id));}render();}catch(error){notify(error.message);}}
 async function click(event){const button=event.target.closest('button');if(!button||button.disabled){if(event.target.hasAttribute('data-dismiss'))closePicker();return;}const attr=button.dataset;
 if(attr.appScope===scope||attr.appLifetime===lifetime||('records'in attr&&records===(attr.records==='true')))return;
 if('appHome'in attr){onHome();return;}if(attr.appScope){scope=attr.appScope;if(scope==='location')lifetime='temporary';modal=null;records=false;render();container.querySelector('.ip-scroll')?.scrollTo(0,0);return;}if(attr.appLifetime){lifetime=attr.appLifetime;modal=null;render();return;}if('records'in attr){records=attr.records==='true';render();return;}if('soundwave'in attr){soundwave=!soundwave;render();return;}
 if(attr.picker){const command=HYPNOSIS_COMMANDS.find(x=>x.id===attr.commandId),d=data(command);modal={id:command.id,type:attr.picker,selected:[...(attr.picker==='parts'?d.partIds:d.targetIds)]};search='';render();return;}
 if('modalCancel'in attr){closePicker();return;}if('modalConfirm'in attr){if(modal){const command=HYPNOSIS_COMMANDS.find(x=>x.id===modal.id),d=data(command);d[modal.type==='parts'?'partIds':'targetIds']=[...modal.selected];if(modal.type==='people'){const valid=new Set(hypnosisBodyParts(names(d)).map(x=>x.id));d.partIds=d.partIds.filter(x=>valid.has(x));}closePicker();}return;}
 if(attr.option&&modal){const value=attr.option;if(modal.selected.includes(value))modal.selected=modal.selected.filter(x=>x!==value);else if(modal.type==='parts'&&modal.selected.length>=5){notify('最多选择 5 处');return;}else modal.selected.push(value);render();return;}
 if('stage'in attr&&!busy){busy=true;render();try{const latest=await getSnapshot(),batch=normalizeHypnosisBatch({soundwave,requests:chosen().map(command=>({...data(command),chatId:sessionChat.id,scope,lifetime,commandId:command.id,locationId:data(command).locationId||latest.location?.id||''}))},latest);const result=await stageHypnosis(batch);if(result?.ok===false)throw Error(result.message||'暂存失败');notify('抵抗结果与催眠操作已加入日程');await refresh();}catch(error){notify(error.message);}finally{busy=false;render();}}
 }
 function input(event){const input=event.target;if(input.hasAttribute('data-picker-search')){search=input.value;render();return;}if(input.dataset.feature){const command=HYPNOSIS_COMMANDS.find(x=>x.id===input.dataset.feature);data(command).enabled=input.checked;render();return;}if(input.dataset.field){const command=HYPNOSIS_COMMANDS.find(x=>x.id===input.dataset.commandId);data(command)[input.dataset.field]=input.value;saveDraft();const badge=container.querySelector(`[data-command-cost="${command.id}"]`);if(badge)badge.innerHTML=cost(command)+'<small> MC</small>';const sum=container.querySelector('[data-batch-cost]');if(sum)sum.innerHTML=total()+' <span>MC</span>';}}
 function keydown(event){if(!modal)return;if(event.key==='Escape'){event.preventDefault();closePicker();}if(event.key==='Tab'){const items=[...container.querySelectorAll('.ip-picker-sheet button,.ip-picker-sheet input')].filter(x=>!x.disabled),first=items[0],last=items.at(-1);if(event.shiftKey&&doc.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&doc.activeElement===last){event.preventDefault();first?.focus();}}}
 const toggle=event=>{const tier=event.target.dataset?.tier;if(tier)event.target.open?opened.add(tier):opened.delete(tier);};
 container.addEventListener('toggle',toggle,true);container.addEventListener('click',click);container.addEventListener('input',input);container.addEventListener('keydown',keydown);void refresh();const stopPolicy=onCharacterContentPolicyReady(()=>void refresh(),win);
 return {refresh,destroy(){destroyed=true;epoch++;stopPolicy();container.removeEventListener('toggle',toggle,true);container.removeEventListener('click',click);container.removeEventListener('input',input);container.removeEventListener('keydown',keydown);}};
}
